Here is a comprehensive pytest suite covering happy paths, edge cases, and error cases:

```python
import pytest


def deep_get(d: dict, keys: str, default=None):
    """Get nested dict value by dot-separated keys."""
    for key in keys.split('.'):
        if isinstance(d, dict):
            d = d.get(key, default)
        else:
            return default
    return d


class TestDeepGetHappyPath:
    def test_simple_top_level_key(self):
        assert deep_get({"a": 1}, "a") == 1

    def test_nested_key(self):
        assert deep_get({"a": {"b": 2}}, "a.b") == 2

    def test_deeply_nested_key(self):
        data = {"a": {"b": {"c": {"d": 4}}}}
        assert deep_get(data, "a.b.c.d") == 4

    @pytest.mark.parametrize("value", [
        "string", 42, 3.14, True, False, [], {}, None
    ])
    def test_various_value_types_returned(self, value):
        """Actual values should be returned, even if falsy or None."""
        assert deep_get({"key": value}, "key", "DEFAULT") == value


class TestDeepGetEdgeCases:
    def test_missing_key_returns_none_default(self):
        assert deep_get({}, "missing") is None

    def test_missing_key_returns_custom_default(self):
        assert deep_get({}, "missing", "DEFAULT") == "DEFAULT"

    def test_missing_nested_key_returns_default(self):
        assert deep_get({"a": {}}, "a.b", "DEFAULT") == "DEFAULT"

    def test_falsy_values_not_replaced_by_default(self):
        """Falsy values (0, False, '', []) are real values, not missing."""
        assert deep_get({"a": 0}, "a", "DEF") == 0
        assert deep_get({"a": False}, "a", "DEF") is False
        assert deep_get({"a": ""}, "a", "DEF") == ""
        assert deep_get({"a": []}, "a", "DEF") == []

    def test_none_value_not_replaced_by_default(self):
        """If the key exists and value is None, return None—not default."""
        assert deep_get({"a": None}, "a", "DEF") is None
        assert deep_get({"a": {"b": None}}, "a.b", "DEF") is None

    def test_intermediate_not_dict_returns_default(self):
        """If path hits a non-dict before the end, return default."""
        assert deep_get({"a": "string"}, "a.b", "DEF") == "DEF"
        assert deep_get({"a": 42}, "a.b", "DEF") == "DEF"
        assert deep_get({"a": None}, "a.b", "DEF") == "DEF"
        assert deep_get({"a": []}, "a.b", "DEF") == "DEF"

    def test_empty_dict_always_returns_default(self):
        assert deep_get({}, "a") is None
        assert deep_get({}, "a.b.c", "DEF") == "DEF"

    def test_empty_string_key_lookup(self):
        """Empty string splits to [''], looking up empty string key."""
        assert deep_get({"": "empty"}, "") == "empty"
        assert deep_get({"": {"": "nested"}}, ".") == "nested"

    def test_leading_trailing_and_consecutive_dots(self):
        """Dots create empty-string keys in the path."""
        assert deep_get({"": {"a": 1}}, ".a") == 1
        assert deep_get({"a": {"": 2}}, "a.") == 2
        assert deep_get({"a": {"": {"b": 3}}}, "a..b") == 3


class TestDeepGetErrorCases:
    @pytest.mark.parametrize("non_dict", [None, "string", 42, 3.14, [], set()])
    def test_non_dict_input_returns_default(self, non_dict):
        """Gracefully handle non-dict `d` by returning default immediately."""
        assert deep_get(non_dict, "a", "DEFAULT") == "DEFAULT"

    @pytest.mark.parametrize("non_string", [None, 123, ["a", "b"], {"a": "b"}])
    def test_non_string_keys_raises_attribute_error(self, non_string):
        """`keys.split('.')` requires a string; anything else raises."""
        with pytest.raises(AttributeError):
            deep_get({"a": 1}, non_string)
